sys_ui_action.script:
(function() {
    var capabilityId = 'c7a53f89906b03107f44b7be9ec8858d';   // Claim Adjuster Summary skill

    var request = {
        executionRequests: [{
            payload: {
                claim: {
                    tableName: current.getTableName(),
                    sysId: current.getUniqueValue(),
                    queryString: ''
                }
            },
            capabilityId: capabilityId
        }],
        mode: 'sync'
    };

    try {
        var output = sn_one_extend.OneExtendUtil.execute(request);
        var result = output.capabilities[capabilityId];

        if (result && result.status == 'success') {
            // The response is JSON text like {"model_output": "..."}
            var summary = JSON.parse(result.response).model_output;
            current.setValue('ai_summary', summary);
            current.update();
            gs.addInfoMessage('AI summary generated. Review it before making any decision.');
        } else {
            gs.addErrorMessage('Could not generate the AI summary. Please try again.');
        }
    } catch (e) {
        gs.addErrorMessage('AI summary failed: ' + e);
    }

    action.setRedirectURL(current);
})();
